a.map(([i,c,p,g,k,M,f=[],m=[]])=>({id:i,system:l,ru:c,en:p,descRu:g,descEn:k,stages:M,related:f,aliases:m})),uh=Ol("well",[["alluvium","Четвертичные отложения","Quaternary deposits","Верхний интервал учебного разреза сложен рыхлыми отложениями. Его проходят при забуривании и закрепляют направлением.","Loose sediments make up the top interval of the teaching section. The conductor supports this shallow part of the borehole.","all",["conductor","clay"]],["clay","Глинистый пласт","Clay bed","Мелкозернистая порода с низкой проницаемостью. Некоторые глинистые породы набухают или осыпаются при взаимодействии с промывочной жидкостью.","This fine-grained bed has low permeability. Some clay-rich rocks can swell or slough when exposed to drilling fluid.","all",["alluvium","surface-casing"]],["sandstone","Песчаник","Sandstone","Обломочная порода, сложенная преимущественно зёрнами песчаной размерности. В зависимости от цементации и строения пор она может обладать различной проницаемостью.","Sandstone is a sedimentary rock made primarily of sand-sized grains. Its permeability varies with cementation and pore structure.","all",["mudstone","reservoir"]],["mudstone","Аргиллит","Mudstone","Плотная литифицированная тонкозернистая порода. В учебном разрезе составляет часть интервала промежуточной колонны.","Mudstone is a lithified, fine-grained sedimentary rock. In this model it occupies part of the intermediate hole section.","all",["intermediate-casing"]],["caprock","Покрышка","Caprock","Малопроницаемый пласт над коллектором. Он препятствует вертикальной миграции углеводородов при сохранённой целостности.","A low-permeability rock layer overlies the reservoir. An intact seal restricts upward migration of hydrocarbons.","all",["reservoir"],["флюидоупор","seal rock"]],["reservoir","Продуктивный пласт","Reservoir interval","Пористая проницаемая порода содержит пластовые флюиды. После крепления скважины приток из показанного интервала поступает через перфорационные каналы.","Porous, permeable rock stores formation fluids. After the well is cased, perforations connect the illustrated reservoir interval to the wellbore.","all",["perforations","caprock"],["пласт-коллектор","pay zone"]],["underburden","Подстилающие породы","Underburden","Породы залегают ниже продуктивного интервала. В макете забой проходит верхнюю часть этой толщи и оставляет место под перфорированным интервалом.","These formations underlie the reservoir. The model extends the bottom of the hole into their upper part, below the perforated interval.","all",["reservoir","borehole-bottom"]],["conductor","Направление","Conductor casing","Первая короткая обсадная колонна закрепляет рыхлый приустьевой интервал. В модели её наружный диаметр составляет 426 мм, а глубина башмака — 50 м.","The short, outermost string supports the shallow hole near the well entrance. It has a 426 mm outside diameter and a shoe depth of 50 m in this model.",Cl,["surface-casing","cement-sheath","guide-shoe"],["conductor","направляющая колонна"]],["surface-casing","Кондуктор","Surface casing","Колонна изолирует верхние горизонты и служит опорой для устьевого оборудования. В учебной схеме колонна Ø324 мм зацементирована до устья, башмак расположен на 600 м.","Surface casing isolates shallow formations and supports the wellhead equipment. The model uses a 324 mm string cemented to surface with its shoe at 600 m.",td,["conductor","casing-hanger","intermediate-casing"]],["intermediate-casing","Промежуточная колонна","Intermediate casing","Колонна перекрывает пройденные интервалы и отделяет их от следующего открытого ствола. В модели трубы Ø245 мм спускают до 1800 м.","Intermediate casing isolates formations already drilled before the next hole section is opened. The 245 mm string reaches 1800 m in the teaching well.",[4,5,6,7,8,9,10],["surface-casing","production-casing"],["техническая колонна","protective casing"]],["production-casing","Эксплуатационная колонна","Production casing","Внутренняя обсадная колонна связывает устье с интервалом заканчивания. В модели трубы Ø168,3 мм доходят до 2800 м, а после цементирования их перфорируют напротив коллектора.","The inner casing string extends from the wellhead through the completion interval. In this 2800 m well, the nominal 168.3 mm casing is cemented and perforated across the reservoir.",[7,8,9,10],["production-tubing","perforations","cement-sheath"]],["cement-sheath","Цементное кольцо","Cement sheath","Затвердевший тампонажный раствор заполняет заданный участок затрубного пространства. Он поддерживает колонну и при надлежащей изоляции препятствует перетокам между пластами.","Set cement occupies a designed interval outside the casing. A competent sheath supports the string and provides zonal isolation.",Cl,["annulus","production-casing"],["цементный камень","annular cement"]],["guide-shoe","Башмак обсадной колонны","Casing shoe","Нижний элемент обсадной колонны с обтекаемым носком помогает пройти неровности ствола. Через проходное отверстие при цементировании раствор выходит в затрубное пространство.","The rounded fitting at the bottom of a casing string guides it past borehole irregularities. Cement slurry can exit through its bore into the annulus.",Cl,["float-collar","shoe-track"],["guide shoe","направляющий башмак"]],["casing-coupling","Муфта обсадной трубы","Casing coupling","Муфта соединяет соседние трубы колонны с резьбовыми концами. На разрезе муфты показаны периодическими утолщениями на наружной поверхности колонн.","A threaded coupling joins adjacent casing joints. On the cutaway, couplings appear as short collars around each string.",Cl,["conductor","production-casing"]],["bow-spring-centralizer","Пружинный центратор","Bow-spring centralizer","Дуги упруго отжимают колонну от стенки ствола. Это помогает обеспечить зазор для распределения тампонажного раствора.","Bowed springs hold casing away from the borehole wall. Stand-off leaves room for slurry to distribute around the string.",[7,8,9,10],["production-casing","cement-sheath"],["центратор обсадной колонны","casing centralizer"]],["float-collar","Муфта с обратным клапаном","Float collar","Муфту устанавливают в составе колонны над башмаком. Встроенный клапан препятствует обратному поступлению раствора из затрубного пространства внутрь обсадной колонны.","A float collar is installed in the casing above the shoe. Its non-return valve limits backflow from the annulus after cement displacement.",[7,8,9,10],["guide-shoe","shoe-track"],["ЦКОД","float equipment"]],["bottom-plug","Нижняя цементировочная пробка","Bottom cementing plug","Пробка разделяет буровой и тампонажный растворы при продавке по обсадной колонне. После посадки пробки мембрана открывает проход для тампонажного раствора.","The bottom plug separates drilling fluid from cement slurry during displacement. Its diaphragm opens after landing to allow slurry to pass.",[7],["float-collar","top-plug"],["продавочная пробка","bottom wiper plug"]],["top-plug","Верхняя цементировочная пробка","Top cementing plug","Сплошная пробка отделяет тампонажный раствор от продавочной жидкости. При её посадке на нижнюю пробку в штатной операции фиксируют рост давления.","A solid top plug separates cement from the displacement fluid. A pressure rise normally indicates that it has landed on the bottom plug.",[7],["bottom-plug","cement-sheath"],["top wiper plug"]],["shoe-track","Башмачный участок колонны","Shoe track","Интервал между обратным клапаном и башмаком остаётся заполненным цементом после продавки. Он удерживает остатки раствора из колонны внутри труб.","The casing interval between the float collar and shoe retains cement after displacement. It keeps the last portion of slurry inside the casing.",[7,8,9,10],["float-collar","guide-shoe"]],["open-hole","Открытый ствол","Open hole","Участок скважины, стенки которого ещё не закреплены обсадной колонной. На схеме он продолжается ниже башмака последней спущенной колонны.","Open hole is a section without casing across its walls. In this view it extends below the last installed casing shoe.",nd,["borehole-bottom","annulus"],["необсаженный ствол","uncased hole"]],["borehole-bottom","Забой","Hole bottom","Нижняя граница пробуренного ствола. Максимальная глубина забоя в учебной модели составляет 2800 м.","The hole bottom marks the deepest drilled point. The example well reaches a final depth of 2800 m.",Cl,["open-hole","pdc-bit"],["bottomhole","total depth","глубина забоя"]],["washout","Каверна","Washout","Локальное расширение открытого ствола из-за размыва или осыпания породы. В модели оно условно показано в одном интервале эксплуатационного ствола.","A washout is a local enlargement caused by erosion or failure of the borehole wall. The teaching section illustrates one enlarged interval in the production hole.",[5,6],["open-hole"]],["casing-hanger","Подвеска обсадной колонны","Casing hanger","Профильная деталь передаёт вес подвешенной колонны на посадочное плечо устьевого корпуса. Узел в сборе организует герметизируемый переход к межколонному пространству.","A casing hanger transfers string weight to a landing shoulder in the wellhead. The assembled hanger provides an interface for sealing the casing annulus.",td,["surface-casing","tubing-hanger"]],["annulus","Кольцевое пространство","Annulus","Кольцевой зазор находится между двумя трубами или между трубой и стенкой ствола. Во время показанного бурения раствор возвращается по зазору снаружи бурильной колонны.","An annulus is the space around a pipe, bounded by another pipe or by the borehole wall. Drilling fluid returns up this space in the illustrated drilling stages.",nd,["drill-pipe","cement-sheath"],["затрубное пространство","annular space"]]]),ch=Ol("str",[["drill-pipe","Бурильная труба","Drill pipe","Полые стальные трубы соединяют долото и КНБК с приводом на поверхности. Промывочная жидкость движется внутри колонны к долоту.","Hollow steel joints connect the downhole assembly to the surface drive. Drilling fluid travels inside the drillstring to the bit.",Zs,["tool-joint","drill-collar"],["бурильная колонна","drillstring"]],["tool-joint","Бурильный замок","Tool joint","Утолщённые резьбовые концы соединяют бурильные трубы. Наружный диаметр замка обычно больше диаметра тела трубы.","Thick threaded end connections join drill pipe joints. A tool joint usually has a greater outside diameter than the pipe body.",Zs,["drill-pipe","crossover-sub"]],["drill-collar","Утяжелённая бурильная труба","Drill collar","Массивная толстостенная труба внизу колонны помогает прикладывать нагрузку к долоту. Промывочная жидкость проходит по её внутреннему каналу.","A thick-walled tubular provides part of the weight on bit. Drilling fluid still passes through its central bore.",Zs,["heavy-weight-drill-pipe","near-bit-stabilizer"],["УБТ"]],["heavy-weight-drill-pipe","Тяжёлая бурильная труба","Heavy-weight drill pipe","Труба повышенной массы служит переходной ступенью между УБТ и обычными бурильными трубами. Утолщения защищают тело трубы при контакте со стенкой.","Heavy-weight drill pipe provides a stiffness transition between drill collars and drill pipe. Upsets help protect the pipe body from wall contact.",[5],["drill-collar","drill-pipe"],["ТБТ","HWDP"]],["near-bit-stabilizer","Наддолотный калибратор","Near-bit stabilizer","Лопасти приближаются к стенке ствола и ограничивают боковое перемещение КНБК. Размещение опоры рядом с долотом влияет на поведение компоновки.","Blades approach the borehole wall and limit lateral movement of the bottomhole assembly. A near-bit position affects how the assembly responds to side loads.",Zs,["pdc-bit","drill-collar"],["стабилизатор","КНБК","BHA"]],["bit-sub","Наддолотный переводник","Bit sub","Короткая деталь обеспечивает резьбовое сопряжение долота с соседним инструментом. Она показана непосредственно над долотом в одной из учебных компоновок.","This short sub provides the threaded connection between the bit and the next tool. It is shown immediately above the bit in one of the example assemblies.",[2],["tricone-bit","crossover-sub"]],["crossover-sub","Резьбовой переводник","Crossover sub","Переходной элемент соединяет инструменты с разными типоразмерами резьбы. Промывочный канал сохраняет непрерывность потока внутри компоновки.","A crossover connects tools with different threaded connections. Its through-bore maintains the drilling-fluid passage.",[5],["tool-joint","drill-collar"]],["tricone-bit","Трёхшарошечное долото","Tricone bit","Три шарошки вращаются на цапфах и разрушают породу при перекатывании по забою. В модели долото Ø490 мм показано извлечённым после крепления направления, а Ø393,7 мм работает в интервале под кондуктор.","Three rolling cones crush and chip rock as they move across the hole bottom. The 490 mm bit rests on the rig floor after the conductor is set, while the 393.7 mm bit is shown drilling the next section.",[1,2],["roller-cone","bit-nozzle"],["шарошечное долото","roller cone bit"]],["roller-cone","Шарошка","Roller cone","Конический рабочий элемент вращается на опоре внутри долота. Зубья или твердосплавные вставки передают усилие на породу.","The cone rotates on a bearing in the bit. Teeth or hard inserts apply force to the rock as the cone rolls.",[1,2],["tricone-bit"]],["pdc-bit","Долото PDC","PDC bit","Лопастное долото разрушает породу сдвигом закреплённых резцов. В модели долото Ø215,9 мм формирует эксплуатационный ствол.","Fixed cutters on the blades shear the rock. The 215.9 mm PDC bit opens the final hole section in this model.",[5],["pdc-cutter","bit-nozzle"],["долото с алмазными резцами","polycrystalline diamond compact bit"]],["pdc-cutter","Поликристаллический алмазный резец","PDC cutter","Рабочая алмазная поверхность соединена с твердосплавной подложкой. Резцы распределены по лопастям долота для перекрытия площади забоя.","A polycrystalline diamond table is bonded to a carbide substrate. Cutters are distributed across the blades to cover the hole bottom.",[5],["pdc-bit"]],["bit-nozzle","Промывочная насадка долота","Bit nozzle","Насадка направляет струю бурового раствора к забою. Поток очищает рабочие поверхности и уносит шлам в кольцевое пространство.","A nozzle directs a fluid jet at the hole bottom. Flow cleans the cutting structure and carries cuttings into the annulus.",[1,2,5],["tricone-bit","pdc-bit","annulus"],["гидромониторная насадка","jet nozzle"]],["mud-motor","Винтовой забойный двигатель","Positive displacement motor","Поток раствора приводит во вращение ротор винтовой пары. Выходной вал передаёт момент долоту в забойной компоновке.","Drilling fluid drives the rotor of a positive displacement power section. The output shaft transmits torque to the bit.",[5],["pdc-bit","mwd-tool"],["ВЗД","mud motor","PDM"]],["mwd-tool","Телесистема MWD","MWD tool","Прибор регистрирует параметры траектории и другие измеряемые величины во время бурения. В телесистеме с гидроимпульсным каналом данные передаются изменениями давления раствора.","An MWD tool measures trajectory and other parameters while drilling. A mud-pulse system sends data to surface through changes in fluid pressure.",[5],["mud-motor","mud-pulse-transmitter"],["измерения в процессе бурения","measurement while drilling"]],["mud-pulse-transmitter","Гидроимпульсный передатчик","Mud-pulse transmitter","Устройство формирует кодированную последовательность изменений давления раствора. Датчик на поверхности принимает сигнал для декодирования MWD.","The transmitter produces a coded pattern of pressure changes in the drilling fluid. A surface sensor receives the signal for MWD decoding.",[5],["mwd-tool"],["пульсатор","mud pulser"]],["drilling-jar","Бурильный ясс","Drilling jar","Инструмент создаёт осевой удар по компоновке при прихвате. Он устанавливается в колонне там, где ударное усилие можно передать к месту прихвата.","A drilling jar delivers an axial impact to a stuck assembly. It sits in the string where the impact can be transmitted to the stuck point.",[5],["drill-collar","heavy-weight-drill-pipe"],["ударный механизм","jar"]],["logging-sonde","Каротажный зонд","Logging sonde","Скважинный прибор записывает физические параметры пород вдоль ствола. В показанной стадии его спускают на кабеле в открытый эксплуатационный интервал.","A logging sonde measures formation properties along the hole. In this stage a cable conveys it into the uncased production interval.",[6],["logging-cable","open-hole"],["ГИС","wireline logging tool"]],["logging-cable","Каротажный кабель","Electric logging cable","Армированный кабель несёт массу инструмента и обеспечивает питание и обмен данными. Длина спущенного кабеля входит в систему определения глубины измерения.","Armored electric line supports, powers and communicates with the logging tool. Cable payout contributes to locating measurements by depth.",[6],["logging-sonde"],["геофизический кабель","electric line","wireline"]]]),dh=Ol("prod",[["tubing-head","Трубная головка","Tubing head spool","Корпус устьевой обвязки принимает подвеску НКТ и соединяется с фонтанной ёлкой. Боковой отвод позволяет работать с затрубным пространством.","The spool supports the tubing hanger beneath the tree. A side outlet gives access to the tubing annulus.",In,["tubing-hanger","tree"]],["tree","Фонтанная ёлка","Christmas tree","Вертикальный устьевой узел объединяет запорные органы и отвод продукции. В учебной версии на освоении и при ЭЦН показана фонтанная ёлка с боковым выходом.","The tree provides valves and outlets above the tubing hanger. This cutaway shows a vertical tree for completion and ESP operation.",In,["master-valve","production-wing-valve","wellhead-gauge"],["фонтанная арматура","production tree"]],["master-valve","Стволовая задвижка","Master valve","Задвижка на вертикальном проходе перекрывает поток из НКТ. Она расположена ниже бокового отвода фонтанной ёлки.","The master valve closes the vertical production bore. It is located on the tree below the lateral outlets.",In,["tree","swab-valve"],["коренная задвижка","master gate valve"]],["production-wing-valve","Задвижка выкидной линии","Production wing valve","Задвижка управляет боковым выходом продукции. Она установлена между стволом ёлки и последующей обвязкой выкидной линии.","The wing valve isolates the lateral production outlet. On the model it sits between the tree bore and the downstream flowline fittings.",In,["tree","flowline","production-choke"],["боковая задвижка","wing valve"]],["swab-valve","Верхняя задвижка","Swab valve","Верхняя задвижка на вертикальном проходе фонтанной ёлки обеспечивает доступ инструментов через устье. При обычной добыче через боковой отвод её держат закрытой.","The top tree valve gives tools access to the vertical bore. It is normally closed when production flows through the wing outlet.",In,["tree","master-valve"],["буферная задвижка"]],["production-choke","Регулируемый штуцер","Production choke","Штуцер изменяет проходное сечение и создаёт контролируемый перепад давления. В учебной арматуре он стоит после боковой задвижки.","The choke varies the flow area to impose a controlled pressure drop. It sits downstream of the wing valve in the model tree.",In,["production-wing-valve","flowline"]],["wellhead-gauge","Устьевой манометр","Wellhead pressure gauge","Манометр показывает давление в точке подключения к арматуре. В схеме круглый прибор расположен на коротком отводе.","A gauge displays pressure at its connection to the tree. The model shows a dial instrument on a short pressure tap.",In,["tree","tubing-head"]],["flowline","Выкидная линия продукции","Production flowline","Трубопровод отводит добываемую смесь от устья к системе сбора. Его положение зависит от схемы обвязки скважины.","The flowline takes produced fluids from the wellhead to the gathering system. Its routing depends on the chosen surface completion.",In,["production-wing-valve","production-tubing"],["выкидной трубопровод"]],["production-tubing","Насосно-компрессорные трубы","Production tubing","Внутренняя колонна доставляет пластовую продукцию на поверхность. В учебной схеме наружный диаметр НКТ 73 мм.","This inner tubular string carries produced fluid to surface. The tubing has a 73 mm outside diameter in the example well.",In,["production-casing","tubing-hanger","packer"],["НКТ","tubing"]],["tubing-hanger","Подвеска НКТ","Tubing hanger","Подвеска удерживает колонну насосно-компрессорных труб в трубной головке. Уплотнения герметизируют её посадку в корпусе.","The tubing hanger supports the tubing string inside the tubing head. Seals close the annular interface with the housing.",In,["production-tubing","tubing-head"]],["packer","Пакер","Production packer","Уплотнительный узел перекрывает кольцевой зазор между НКТ и обсадной колонной. На показанном заканчивании он отделяет затрубное пространство от продуктивного интервала.","The packer seals the space between tubing and casing. It separates the tubing annulus from the reservoir interval in the shown completion.",[8,9],["production-tubing","perforations"]],["perforations","Перфорационные каналы","Perforation tunnels","Каналы проходят через стенку обсадной трубы и цементное кольцо в коллектор. Через них пластовая жидкость поступает в ствол.","These tunnels penetrate the casing wall and cement sheath into the formation. Reservoir fluid enters the well through them.",In,["reservoir","production-casing"],["перфорация","perforations"]],["landing-nipple","Посадочный ниппель","Landing nipple","Профильный элемент в составе НКТ служит посадочным местом для совместимого скважинного устройства. Проход ниппеля остаётся открыт, когда устройство извлечено.","A machined profile in the tubing accepts a compatible downhole device. The bore remains open when the device is removed.",[8,9],["production-tubing","packer"]]]).map(l=>ah.has(l.id)?{...l,excludeLift:"srp"}:l),ph=Ol("prod",[["pumping-tee","Устьевой тройник ШГН","Pumping tee","Тройник отводит продукцию из насосно-компрессорных труб в выкидную линию. Через верхний проход устьевой шток входит в НКТ под сальником.","The tee directs tubing fluid to the flowline. The polished rod passes into the tubing through the stuffing box above it.",He,["stuffing-box","flowline","tubing-head"]],["pumping-unit-skid","Рама станка-качалки","Pumping-unit base","Рама служит общей опорой для стойки, редуктора и привода. Она распределяет нагрузки этих узлов на фундамент.","The base supports the post, gearbox and prime mover. It spreads equipment loads into the foundation.",He,["samson-post","pumpjack-gearbox"],["станок-качалка","beam pumping unit"]],["samson-post","Стойка станка-качалки","Samson post","Стойка поднимает опору балансира над рамой. Усилия от качающегося балансира передаются через неё на основание.","The post supports the walking-beam pivot above the base. Beam loads pass through it into the foundation.",He,["walking-beam","pumping-unit-skid"]],["walking-beam","Балансир станка-качалки","Walking beam","Балансир качается на опоре стойки под действием кривошипно-шатунного механизма. Его устьевой конец задаёт ход подвески штанг.","The beam oscillates on the post pivot as the crank linkage turns. The wellhead end produces the rod string stroke.",He,["horsehead","pumpjack-pitman"]],["horsehead","Головка балансира","Horsehead","Криволинейная головка направляет канатную подвеску по мере качания балансира. Это помогает удерживать линию тяги над устьем.","The curved horsehead guides the bridle as the beam rocks. Its profile keeps the pull aligned over the wellhead.",He,["walking-beam","rod-bridle"]],["rod-bridle","Канатная подвеска штанг","Wireline bridle","Два участка каната передают усилие головки балансира к траверсе. В модели они движутся вместе с устьевым штоком.","Two wireline legs transfer load from the horsehead to the carrier bar. They move with the polished rod in the model.",He,["horsehead","carrier-bar"]],["carrier-bar","Траверса подвески штанг","Carrier bar","Траверса соединяет канатную подвеску с зажимом устьевого штока. Она передаёт подъёмное усилие на колонну штанг.","The carrier bar connects the bridle to the polished-rod clamp. It transfers lifting force to the rod string.",He,["rod-bridle","polished-rod"]],["pumpjack-pitman","Шатун станка-качалки","Pitman arm","Шатун передаёт движение от вращающегося кривошипа к хвосту балансира. Пара шатунов расположена симметрично относительно установки.","The pitman arm links the rotating crank to the rear of the walking beam. The model has a pair on opposite sides of the unit.",He,["pumpjack-crank","walking-beam"]],["pumpjack-crank","Кривошип станка-качалки","Pumping-unit crank","Кривошип закреплён на выходном валу редуктора и ведёт шарнир шатуна по окружности. Расстояние от центра вала до шарнира влияет на ход штока.","The crank rotates with the gearbox output shaft and carries the pitman pin around a circle. Pin radius helps determine the polished-rod stroke.",He,["pumpjack-pitman","crank-counterweight","pumpjack-gearbox"]],["crank-counterweight","Кривошипный противовес","Crank counterweight","Груз на кривошипе частично уравновешивает нагрузку колонны штанг и поднимаемой жидкости. Так снижаются перепады крутящего момента привода.","A crank-mounted weight balances part of the rod and fluid load. Counterbalancing reduces variation in drive torque over a cycle.",He,["pumpjack-crank"]],["pumpjack-gearbox","Редуктор станка-качалки","Pumping-unit gearbox","Редуктор снижает частоту вращения и повышает крутящий момент на валу кривошипов. На раме он расположен между стойкой и двигателем.","The gear reducer lowers speed and increases available crank torque. It mounts on the base between the post and the motor.",He,["pumpjack-motor","pumpjack-crank"]],["belt-drive","Клиноремённая передача","V-belt drive","Ремни передают вращение от двигателя к входному валу редуктора. В макете ремни и шкивы показаны со стороны привода.","V-belts connect the motor to the gearbox input. The belts and sheaves are visible on the drive side of the model.",He,["pumpjack-motor","pumpjack-gearbox"]],["pumpjack-motor","Электродвигатель станка-качалки","Pumping-unit motor","Двигатель вращает входной вал редуктора через ремённую передачу. Редуктор и кривошип преобразуют это движение в ход штанг.","The motor drives the gearbox input through belts. The gearbox and crank linkage convert this rotation into rod motion.",He,["belt-drive","pumpjack-gearbox"]],["pumpjack-brake","Тормоз станка-качалки","Pumping-unit brake","Тормоз удерживает остановленный механизм в выбранном положении при предусмотренной процедуре. Ленточный тормоз показан на входном валу редуктора.","The brake holds the stopped unit in position during the applicable procedure. The model shows a band brake on the gearbox input shaft.",He,["pumpjack-gearbox"]],["stuffing-box","Устьевой сальник","Stuffing box","Уплотнительный узел допускает возвратно-поступательное движение полированного штока. Набивка препятствует выходу продукции вокруг штока.","The sealing assembly allows the polished rod to reciprocate through the wellhead. Packing limits leakage around the rod.",He,["polished-rod","tubing-head"]],["polished-rod","Полированный устьевой шток","Polished rod","Шток передаёт движение траверсы колонне насосных штанг. Гладкая поверхность работает в контакте с уплотнением устьевого сальника.","This rod transfers motion from the carrier bar to the sucker rods. Its polished surface moves through the stuffing-box packing.",He,["stuffing-box","sucker-rods"]],["sucker-rods","Насосные штанги","Sucker rods","Соединённые штанги передают возвратно-поступательное движение к насосу. В модели колонна штанг проходит по центру НКТ.","A string of joined rods transmits reciprocating motion to the downhole pump. The string runs along the center of the tubing.",He,["polished-rod","rod-pump-plunger"],["штанговая колонна","rod string"]],["sucker-rod-coupling","Муфта насосной штанги","Sucker-rod coupling","Резьбовая муфта соединяет две соседние насосные штанги. На разрезе соединения показаны небольшими утолщениями вдоль колонны.","Threaded couplings connect adjacent sucker rods. They appear as small enlargements along the rod string in the cutaway.",He,["sucker-rods"]],["rod-pump-barrel","Цилиндр штангового насоса","Rod pump barrel","Цилиндр образует рабочую камеру насоса и направляет ход плунжера. В этой компоновке цилиндр неподвижен относительно НКТ.","The barrel forms the pump chamber and guides the plunger. It is stationary relative to the tubing in this example.",He,["rod-pump-plunger","standing-valve"],["ШГН","SRP","sucker rod pump"]],["rod-pump-plunger","Плунжер штангового насоса","Rod pump plunger","Плунжер движется в цилиндре под действием колонны штанг. Перемещение меняет объём камеры и создаёт перепад давления на клапанах.","The rod string moves the plunger inside the barrel. Changing chamber volume creates the pressure differences that operate the valves.",He,["sucker-rods","traveling-valve"]],["standing-valve","Всасывающий клапан ШГН","Standing valve","Неподвижный клапан стоит на входе цилиндра. Во время хода вверх он пропускает жидкость в рабочую камеру при достаточном перепаде давления.","The standing valve sits at the barrel inlet. During the upstroke it opens to admit fluid when the pressure difference is sufficient.",He,["rod-pump-barrel","traveling-valve"]],["traveling-valve","Нагнетательный клапан ШГН","Traveling valve","Клапан перемещается вместе с плунжером. При ходе вниз он открывает жидкости путь из рабочей камеры над плунжер.","The traveling valve moves with the plunger. During the downstroke it lets fluid pass from the barrel chamber to the space above the plunger.",He,["rod-pump-plunger","standing-valve"],["подвижный клапан","travelling valve"]]]).map(l=>({...l,lift:"srp"})),fh=Ol("prod",[["esp-cabinet","Станция управления ЭЦН","ESP control panel","Станция управляет пуском и отключением погружного двигателя, а также обрабатывает сигналы защиты. В макете она установлена рядом с трансформатором.","The panel starts and stops the downhole motor and handles protection signals. It sits next to the transformer in the surface layout.",He,["esp-transformer","esp-motor"]],["esp-transformer","Трансформатор ЭЦН","ESP transformer","Трансформатор согласует напряжение питания с требуемым для погружного двигателя. От станции и трансформатора питание подаётся к устьевому вводу.","The transformer matches the supply voltage to the downhole motor requirement. Surface electrical equipment feeds the wellhead penetrator.",He,["esp-cabinet","esp-penetrator"],["ТМПН","step-up transformer"]],["esp-penetrator","Устьевой кабельный ввод","Wellhead penetrator","Герметичный ввод передаёт питание через границу давления в устьевой обвязке. Он соединяет наземный и скважинный участки электропитания.","The penetrator carries electrical power across the pressure boundary at the wellhead. It connects the surface supply to the downhole cable.",He,["esp-cable","esp-transformer"],["cable feedthrough"]],["esp-cable","Погружной силовой кабель","ESP power cable","Кабель идёт вдоль наружной стороны НКТ и подводит питание к двигателю. Крепления ограничивают его смещение при спуске колонны.","The power cable runs along the outside of the tubing to the downhole motor. Clamps restrain it while the assembly is run.",He,["esp-motor","esp-cable-protector"],["КРБК","ESP cable"]],["esp-cable-protector","Протектор кабеля ЭЦН","Cable protector","Защита удерживает кабель у НКТ и снижает риск повреждения в узких местах. В модели протекторы показаны у нескольких соединений труб.","The protector holds the cable close to the tubing and shields it in tight clearances. The model shows protectors near several tubing connections.",He,["esp-cable","production-tubing"]],["esp-motor","Погружной электродвигатель","ESP motor","Двигатель преобразует электрическую энергию в вращение общего вала агрегата. Он расположен ниже гидрозащиты, в нижней части установки.","The downhole motor converts electrical power to shaft rotation. It sits below the protector at the base of the assembly.",He,["esp-protector","esp-pump"],["ПЭД","submersible motor"]],["esp-protector","Гидрозащита ЭЦН","ESP protector","Узел отделяет масло двигателя от скважинной жидкости и компенсирует изменение его объёма. Вал передаёт вращение к расположенным выше ступеням.","The protector separates motor oil from well fluid and accommodates oil volume changes. The shaft passes through it to the units above.",He,["esp-motor","esp-gas-separator"],["seal section","motor protector"]],["esp-gas-separator","Газосепаратор ЭЦН","ESP gas separator","Узел отделяет часть свободного газа до входа жидкости в насосные ступени. Газ отводится в затрубное пространство, а жидкость поступает в насос.","The separator removes some free gas ahead of the pump stages. Gas vents to the annulus while liquid enters the pump.",He,["esp-pump","esp-protector"]],["esp-pump","Секция центробежного насоса","ESP pump section","Последовательно расположенные ступени поднимают давление жидкости. В собранном агрегате секция находится над входным узлом и нагнетает в НКТ.","A stack of stages increases liquid pressure along the pump. The section sits above the intake assembly and discharges into the tubing.",He,["esp-impeller","esp-diffuser","esp-check-valve"],["ЭЦН","electric submersible pump"]],["esp-impeller","Рабочее колесо ЭЦН","ESP impeller","Вращающееся рабочее колесо передаёт энергию жидкости. Каждое колесо вместе с неподвижным направляющим аппаратом образует ступень.","A rotating impeller transfers energy to the liquid. Each impeller and its stationary diffuser form a pump stage.",He,["esp-diffuser","esp-pump"]],["esp-diffuser","Направляющий аппарат ЭЦН","ESP diffuser","Неподвижные каналы принимают поток после рабочего колеса и преобразуют часть его скоростного напора в давление. Затем поток направляется к следующей ступени.","Stationary passages receive flow from the impeller and convert part of its velocity head into pressure. They guide the liquid into the next stage.",He,["esp-impeller","esp-pump"]],["esp-check-valve","Обратный клапан ЭЦН","ESP check valve","Клапан над насосом препятствует обратному сливу жидкости через ступени после остановки. В модели он стоит в НКТ у выхода из насоса.","A valve above the pump limits reverse flow through the stages after shutdown. It is shown in the tubing near the discharge.",He,["esp-pump","esp-drain-valve"]],["esp-drain-valve","Сбивной клапан ЭЦН","ESP drain valve","При извлечении оборудования клапан позволяет сообщить внутренний объём НКТ с затрубным пространством. Он расположен выше обратного клапана.","The drain valve permits tubing fluid to drain into the annulus during recovery of the equipment. It sits above the check valve.",He,["esp-check-valve","production-tubing"],["dump valve","bleeder valve"]]]).map(l=>({...l,lift:"esp"})),hh=[...uh,...ch,...dh,...ph,...fh],bn=(l,a,i,c)=>({ru:l,en:a,descRu:i,descEn:c}),ct=[bn("Монтаж буровой","Site preparation & rig-up","На площадке собирают основание, мачту и талевую систему. Подключают энергоблок и циркуляционную систему. Положение будущего устья задано осью ротора.","Crews assemble the substructure, mast and hoisting system. The power and fluid systems are connected. The rotary table marks the axis of the planned well."),bn("Направление","Conductor hole & casing","Бурят верхний интервал до 50 м. Направление Ø426 мм закрепляет устьевую часть ствола. Цемент заполняет зазор снаружи трубы до поверхности.","The first interval reaches 50 m. A 426 mm conductor supports the shallow part of the borehole. Cement fills the annulus around the pipe up to the surface."),bn("Бурение под кондуктор","Surface hole drilling","Долото Ø393,7 мм проходит интервал до 600 м. Раствор спускается по бурильной колонне и возвращается по затрубью, вынося шлам. На поверхности его очищают и возвращают в систему. Синие метки показывают подачу, охристые — возврат.","A 393.7 mm bit drills to 600 m. Mud travels down the drillstring and carries cuttings back up the annulus. Surface equipment cleans the returning fluid before recirculation. Blue markers show supply flow and ochre markers show return flow."),bn("Кондуктор и ПВО","Surface casing & BOP","Кондуктор Ø324 мм изолирует верхние горизонты. За колонной показано цементное кольцо до устья. На колонной головке установлен блок превенторов.","A 324 mm surface casing string isolates shallow formations. The cement sheath extends to the wellhead in this example. The blowout preventer stack sits above the casing head."),bn("Промежуточная колонна","Intermediate hole & casing","Интервал пробурен до 1 800 м. Промежуточная колонна Ø245 мм перекрывает вышележащие интервалы. Цементное кольцо изолирует породы за колонной.","The intermediate section reaches 1,800 m. A 245 mm casing string covers the formations above the shoe. Cement provides zonal isolation outside the steel."),bn("Вскрытие пласта","Production hole","Долото Ø215,9 мм проходит продуктивный пласт до 2 800 м. В открытом интервале видна компоновка низа бурильной колонны. Изучите долото, двигатель и приборы КНБК.","A 215.9 mm bit drills through the reservoir to 2,800 m. The bottomhole assembly is visible in the open interval. Inspect the bit, motor and downhole instruments."),bn("Каротаж","Wireline logging","Каротажный зонд спускают на кабеле в открытый ствол. Его измерения помогают уточнить границы и свойства пластов. Наземный подъёмник управляет кабелем и глубиной зонда.","A logging tool is run on wireline into the open hole. Measurements help identify formation boundaries and properties. A surface unit controls cable movement and tool depth."),bn("Эксплуатационная колонна","Production casing & cementing","Эксплуатационная колонна Ø168 мм проходит через продуктивный интервал. Центраторы поддерживают зазор вокруг трубы. Цемент отделяет пласт от соседних горизонтов.","The nominal 168 mm production casing crosses the reservoir interval. Centralizers maintain clearance around the pipe. The cement sheath isolates the reservoir from adjacent formations."),bn("Перфорация и освоение","Perforation & completion","Перфорационные каналы соединяют коллектор с внутренним пространством колонны. НКТ дают жидкости путь на поверхность, пакер изолирует затрубье. На устье устанавливают фонтанную арматуру.","Perforation tunnels connect the reservoir to the inside of the casing. Tubing provides a flow path and the packer isolates the annulus. A production tree controls the well at the surface."),bn("Демонтаж буровой","Rig-down","Буровую установку разбирают по блокам и вывозят с площадки. На поверхности остаётся устье с фонтанной арматурой. Конструкция обсаженного ствола сохраняется.","Rig modules are dismantled and taken off site. The wellhead and production tree remain on the pad. The cased and completed bore remains in place."),bn("Механизированная добыча","Artificial-lift production","Станок-качалка приводит штанговый насос через колонну штанг. В альтернативном варианте ЭЦН поднимает жидкость по НКТ с помощью погружного электродвигателя. Переключите установки, чтобы сравнить путь передачи энергии.","A beam pumping unit drives the downhole rod pump through a rod string. In the alternative, a submersible motor drives the ESP and sends fluid up the tubing. Switch between lift systems to compare how power reaches the pump.")].map((l,a)=>({...l,depth:Zd[a]})),Pr={struct:["Конструкции","Structures","#a49886"],hoist:["Талевая система","Hoisting","#d98b4e"],rot:["Вращение","Rotating equipment","#55585d"],str:["Бурильная колонна","Drillstring & BHA","#6a6d72"],circ:["Циркуляция","Mud circulation","#5f93b8"],wc:["Контроль скважины","Well control","#c5584c"],power:["Энергетика и управление","Power & controls","#8d9180"],well:["Ствол и геология","Well & geology","#4f9b95"],prod:["Добыча","Production","#a1693f"],service:["Сервисная техника","Service equipment","#8d778d"]},mh=["overview","walk","well","deck","mud","bop","bore","bottom","cabin","monkeyboard","wellhead"],Gs=(l,a)=>a.includes(l)?l:a[0],rd=(l,a,i)=>/^\d+$/.test(l??"")&&Number(l)<=i?Number(l):a;function gh(l){const a=new URLSearchParams(l),i=rd(a.get("stage"),3,10),c=Gs(a.get("view"),mh),p=i>=9&&["walk","deck","mud","bop","cabin","monkeyboard"].includes(c)||c==="bop"&&(i<3||i>7)||c==="wellhead"&&i<8||["well","bottom"].includes(c)&&!ct[i].depth?"overview":c;return{stage:i,lang:Gs(a.get("lang"),["ru","en","both"]),drive:Gs(a.get("drive"),["topdrive","kelly"]),lift:Gs(a.get("lift"),["srp","esp"]),view:p,selected:a.get("part")||null,depth:p==="well"?rd(a.get("depth"),0,ct[i].depth):0}}function vh(l){const a=new URLSearchParams;for(const i of["stage","lang","drive","lift","view"])a.set(i,l[i]);return l.selected&&a.set("part",l.selected),l.depth&&l.view==="well"&&a.set("depth",l.depth),"?"+a}function vu(l){return l.stages==="all"?ct.map((a,i)=>i):l.stages==="rig"?ct.slice(0,9).map((a,i)=>i):l.stages}function eo(l,a){return vu(l).includes(a.stage)&&(!l.drive||l.drive===a.drive)&&(!l.lift||l.lift===a.lift)&&(a.stage!==10||l.excludeLift!==a.lift)}function lu(l,a){const i=vu(l),c={...a,selected:l.id,depth:0,view:"overview"};return c.stage=i.reduce((p,g)=>Math.abs(g-a.stage)<Math.abs(p-a.stage)?g:p,i[0]),c.drive=l.drive??a.drive,c.lift=l.lift??(c.stage===10&&l.excludeLift===a.lift?a.lift==="srp"?"esp":"srp":a.lift),c}const yh=[["ГОСТ 16293-89","Наземные комплектные буровые установки","Land drilling rig specification","https://protect.gost.ru/gost/details/da19235f-a2c6-45e7-b848-3dd2e6713885"],["ГОСТ 13862-90","Противовыбросовое оборудование","Blowout prevention equipment","https://protect.gost.ru/gost/details/034d753a-4b7e-4ebf-b6bc-b57cbef26a66"],["ГОСТ 31446-2017","Обсадные и насосно-компрессорные трубы","Casing and tubing","https://protect.gost.ru/gost/details/c99d20b0-9748-4915-9608-953ca5053ddc"],["ГОСТ 31835-2012","Штанговые скважинные насосы","Downhole rod pumps","https://protect.gost.ru/gost/details/6eaf2ca0-f8db-4194-850b-f62eef64553d"],["ГОСТ Р 71010-2023","Буровые насосы","Drilling pumps","https://protect.gost.ru/gost/details/468fc368-a475-4418-a5c7-24734f4cd660"],["API Spec 5CT / 6A / 7K / 16A","Обсадные трубы, арматура и ПВО","Casing, wellhead and drill-through equipment","https://www.api.org/products-and-services/standards/digital-catalog"],["IADC Lexicon","Термины конструкции и оборудования скважины","Well construction and equipment terminology","https://iadclexicon.org/casing/"],["IADC Drilling Manual","Наземное оборудование и буровые системы","Land rig equipment and drilling systems","https://store.iadc.org/product/iadc-drilling-manual-13th-edition"],["SLB Energy Glossary","Оборудование и термины механизированной добычи","Artificial lift equipment and terminology","https://glossary.slb.com/terms/s/sucker_rod_pump"]],ln=[3,4,5,6,7],wh=[3,4,5,6,7,8,9,10],kh={struct:[["mast","Буровая мачта","Drilling mast","Несёт кронблок и нагрузки от талевой системы. Открытая сторона секционной мачты облегчает подачу труб.","The mast supports the crown block and carries the hoisting loads. Its open face provides access for pipe handling.","rig",null,["crown-block","mast-legs"]],["mast-legs","Ноги мачты","Mast legs","Продольные пояса передают усилия от верхней площадки на основание. Секции соединяются в узлах фермы.","The main chords transfer loads from the crown platform to the substructure. Connections at the truss nodes join the mast sections."],["mast-braces","Раскосы мачты","Mast diagonal braces","Диагональные элементы связывают пояса в жёсткую ферму. Они воспринимают сдвиг и удерживают заданную геометрию секций.","Diagonal members tie the chords into a stiff truss. They resist shear and maintain the shape of the mast sections."],["mast-pins","Пальцы соединения секций","Mast section pins","Пальцы проходят через проушины соседних секций. Разъёмное соединение упрощает сборку мачты из транспортных блоков.","Pins pass through the lugs of adjacent mast sections. The removable joints allow the mast to be assembled from transportable sections."],["mast-shoes","Опорные шарниры мачты","Mast base hinges","Шарнирные опоры расположены у нижних концов ног. Они задают ось поворота при подъёме мачты.","The hinged supports sit at the bottom of the mast legs. They provide the pivot axis for raising the mast."],["substructure","Подвышечное основание","Rig substructure","Стальные блоки воспринимают нагрузки от мачты, ротора и труб. Под поднятым полом остаётся пространство для устьевого оборудования.","The steel substructure carries loads from the mast, rotary table and pipe. The elevated drill floor provides clearance for wellhead equipment."],["foundation-mats","Опорные маты","Rig mats","Маты распределяют нагрузку от опор на подготовленную площадку. Модель показывает их под основаниями буровой.","Rig mats spread support loads over the prepared location. They are shown beneath the rig skids in this model."],["drill-floor","Пол буровой","Drill floor","Это рабочая площадка вокруг центра скважины. Здесь размещают ротор и оборудование для соединения труб.","The drill floor surrounds the well centre. It supports the rotary table and the equipment used to make up tubulars."],["crown-platform","Подкронблочная рама","Crown platform frame","Верхняя рама связывает пояса мачты и служит опорой кронблока. Через неё нагрузка шкивов передаётся на несущие элементы.","The top frame ties the mast chords together and supports the crown block. It distributes sheave loads to the main structural members."],["monkeyboard","Балкон верхового рабочего","Derrickman’s platform","Площадка для работы с верхними концами свечей находится высоко на мачте. С неё доступны пальцы магазина свечей.","This elevated work platform provides access to the upper ends of stands. The fingerboard is mounted alongside it.","rig",null,["fingerboard","setback"],["monkeyboard","monkey board","балкон верхового"]],["fingerboard","Пальцы магазина свечей","Fingerboard","Ряды пальцев образуют ячейки для верхних концов свечей. Нижние концы свечей опираются на подсвечник.","Rows of fingers form slots that retain the tops of pipe stands. The feet of the stands rest on the setback floor."],["setback","Подсвечник","Setback area","Усиленный участок пола воспринимает вес вертикально установленных свечей. Он расположен под магазином свечей.","The reinforced floor section carries the weight of upright pipe stands. It lies below the fingerboard."],["pipe-stand","Свеча бурильных труб","Drill pipe stand","Свеча состоит из нескольких свинченных труб. Во время спуско-подъёмных операций её устанавливают вертикально на подсвечник.","A stand is made up of several connected joints of drill pipe. During tripping it can be racked upright in the setback area."],["access-stairs","Маршевая лестница","Access stairway","Лестничный марш соединяет основание с буровым полом. Ступени опираются на наклонные тетивы.","The stairway connects ground level to the drill floor. Its treads are supported by inclined stringers."],["mast-ladder","Лестница мачты","Mast ladder","Вертикальная лестница проходит вдоль пояса мачты. По ней добираются до площадок обслуживания.","The vertical ladder follows one mast chord. It provides access to the elevated maintenance platforms."],["guardrails","Ограждение бурового пола","Drill floor guardrail","Ограждение обозначает и защищает открытые края рабочего настила. Проходы сохраняются у лестницы и зоны подачи труб.","The guardrail protects open edges of the drill floor. Openings are left at the stairway and pipe-handling access."],["catwalk","Приёмный мост","Catwalk","Горизонтальная площадка принимает трубы со стеллажей. Она совмещена с траекторией подачи трубы к буровому полу.","The horizontal catwalk receives joints from the pipe racks. It aligns the pipe with the route to the drill floor."],["pipe-ramp","Наклонные мостки","Pipe ramp","Мостки соединяют приёмный мост с проёмом бурового пола. По наклонному жёлобу подают отдельные трубы.","The inclined ramp connects the catwalk to the drill floor opening. Its trough guides individual joints as they are picked up."],["pipe-racks","Трубные стеллажи","Pipe racks","Поперечные балки поддерживают трубы на поверхности. Стойки ограничивают перемещение крайнего ряда.","Transverse beams support tubulars at ground level. End posts restrain the outer row of stored pipe."],["racked-pipe","Трубы на стеллаже","Racked drill pipe","Отдельные трубы хранятся горизонтально рядом с приёмным мостом. Их резьбовые концы защищены перед подачей на пол.","Individual joints are stored horizontally alongside the catwalk. Thread protectors cover their ends before they are brought to the floor."],["mast-light","Прожектор мачты","Mast floodlight","Прожектор освещает участок бурового пола и подвешенное оборудование. Светильники закреплены на металлоконструкциях.","The floodlight illuminates the drill floor and suspended equipment. Fixtures are mounted on the mast structure."],["rig-wind-vane","Флюгер","Wind vane","Подвижная стрелка показывает направление ветра у верхней точки мачты. Флюгер используется для наблюдения за местными условиями.","The pivoting vane indicates wind direction at the top of the mast. It provides a local indication of wind conditions."],["service-platform","Площадка обслуживания","Service platform","Промежуточный настил даёт доступ к участку мачты. Он опирается на ферму и снабжён ограждением.","The intermediate platform gives access to equipment on the mast. The truss supports the deck and its guardrail."],["vee-door","Проём подачи труб","V-door","Проём в ограждении совмещён с наклонными мостками. Через него труба выходит на буровой пол.","The V-door is aligned with the pipe ramp. It provides a clear route for pipe entering or leaving the drill floor."]],hoist:[["crown-block","Кронблок","Crown block","Неподвижный блок расположен в вершине мачты. Шкивы изменяют направление ветвей талевого каната.","The stationary block sits at the top of the mast. Its sheaves redirect the parts of the drilling line.","rig",null,["traveling-block","drilling-line"]],["crown-sheaves","Шкивы кронблока","Crown sheaves","Канат огибает шкивы по канавкам. Ось и опоры передают их нагрузку на раму кронблока.","The line runs in the grooves around the sheaves. Their shaft and bearings transmit load into the crown frame."],["traveling-block","Талевый блок","Traveling block","Подвижная обойма шкивов перемещается между буровым полом и кронблоком. На ней подвешено рабочее оборудование.","The traveling block moves between the drill floor and the crown block. It carries the suspended hoisting and rotating equipment.","rig",null,["crown-block","drilling-hook"],["travelling block"]],["traveling-sheaves","Шкивы талевого блока","Traveling block sheaves","Шкивы расположены в подвижной обойме. Ветви огибающего их каната распределяют нагрузку подвески.","These sheaves are carried by the traveling block. The reeved line parts share the suspended load."],["drilling-hook","Буровой крюк","Drilling hook","Крюк устанавливают под талевым блоком. Он служит для подвешивания соответствующих грузозахватных и вращательных узлов.","The drilling hook hangs beneath the traveling block. It provides an attachment point for hoisting and rotary assemblies."],["elevator-links","Элеваторные штропы","Elevator links","Пара стальных тяг соединяет подвеску и элеватор. Тяги передают вес поднимаемой трубы на талевую систему.","A pair of steel links connects the elevator to the suspension. The links transmit tubular weight to the hoisting system.","rig",null,["elevator","traveling-block"],["elevator bails","штропы"]],["elevator","Трубный элеватор","Pipe elevator","Разъёмный захват закрывается вокруг трубы. Вес трубы передаётся на штропы через опорную поверхность захвата.","The hinged elevator closes around a tubular. Its bearing shoulder transfers pipe weight to the elevator links."],["drilling-line","Талевый канат","Drilling line","Стальной канат запасован между шкивами кронблока и талевого блока. Несколько ветвей поддерживают подвижную подвеску.","This wire rope is reeved between the crown and traveling blocks. Multiple line parts support the traveling assembly."],["fast-line","Ходовой конец каната","Fast line","Ходовой конец идёт от кронблока к барабану лебёдки. Наматывание и сматывание этой ветви перемещает талевый блок.","The fast line runs from the crown block to the drawworks drum. Spooling this part of the line raises or lowers the traveling block."],["deadline","Неподвижный конец каната","Deadline","Неподвижный конец выходит с кронблока к анкеру основания. Его натяжение используют для измерения нагрузки подвески.","The deadline runs from the crown block to the deadline anchor. Deadline tension can be used to infer hook load."],["deadline-anchor","Крепление неподвижного конца","Deadline anchor","Анкер закрепляет неподвижный конец талевого каната. На нём обычно размещают датчик нагрузки.","The anchor secures the dead end of the drilling line. The deadline load sensor is commonly mounted at this point."],["drawworks","Буровая лебёдка","Drawworks","Лебёдка перемещает подвешенные узлы наматыванием талевого каната. Барабан, привод и тормоз смонтированы на общей раме.","The drawworks moves suspended equipment by spooling the drilling line. Its drum, drive and brake share a common frame."],["drawworks-drum","Барабан лебёдки","Drawworks drum","Ходовой конец укладывается на цилиндрический барабан. Реборды удерживают витки у краёв.","The fast line spools onto the drum. Flanges keep the line wraps within its working width."],["drawworks-brake","Тормоз лебёдки","Drawworks brake","Тормоз замедляет барабан и удерживает подвеску на заданной высоте. Показана схема с тормозным диском и суппортом.","The brake slows the drum and holds the suspended load at the required height. A disc and caliper arrangement is shown."],["drawworks-motor","Привод лебёдки","Drawworks motor","Электродвигатель передаёт крутящий момент на привод барабана. Скорость регулируют при подъёме и спуске.","The electric motor supplies torque to the drum drive. Its speed is controlled during hoisting and lowering."],["deadline-sensor","Датчик веса","Deadline load sensor","Датчик измеряет усилие на креплении неподвижного конца. Система индикации пересчитывает его в оценку нагрузки на крюке.","The sensor measures force at the deadline anchor. The indicator converts this reading into an estimate of hook load."]],rot:[["top-drive","Верхний привод","Top drive","Подвижный силовой узел вращает бурильную колонну сверху. Внутренний канал пропускает промывочную жидкость.","The traveling drive turns the drillstring from its upper end. A through bore carries drilling fluid into the string.","rig","topdrive",["tds-motors","tds-guide"],["СВП","TDS"]],["tds-motors","Двигатели верхнего привода","Top drive motors","Электродвигатели закреплены на силовом корпусе СВП. Через редуктор они вращают главный вал.","The electric motors are mounted on the top drive. They turn the main shaft through the gearbox.","rig","topdrive"],["tds-gearbox","Редуктор СВП","Top drive gearbox","Зубчатая передача согласует скорости двигателя и выходного вала. Корпус воспринимает реактивный момент.","The gearbox matches motor speed to the output shaft speed. Its housing reacts the drilling torque.","rig","topdrive"],["tds-quill","Ствол верхнего привода","Top drive quill","Полый выходной вал соединяет СВП с бурильной колонной. Он передаёт вращение и пропускает буровой раствор.","The hollow output shaft connects the drive to the drillstring. It transmits torque while providing a passage for mud.","rig","topdrive"],["tds-handler","Трубный манипулятор СВП","Top drive pipe handler","Манипулятор ориентирует и удерживает элементы механизма захвата труб. Он установлен под корпусом СВП.","The pipe handler positions the tubular-handling mechanism below the top drive. It supports gripping and handling functions near the top of the string.","rig","topdrive"],["tds-guide","Направляющая СВП","Top drive guide track","Направляющая допускает вертикальный ход СВП. Через каретку она передаёт реактивный момент на мачту.","The guide track allows vertical travel of the top drive. Its carriage transfers reaction torque to the mast.","rig","topdrive"],["tds-carriage","Каретка СВП","Top drive carriage","Роликовая каретка перемещается по направляющей вместе с силовым блоком. Она не даёт корпусу произвольно поворачиваться.","The roller carriage travels with the drive on its guide track. It restrains rotation of the drive housing.","rig","topdrive"],["upper-ibop","Кран верхнего привода","Top drive internal BOP","Шаровой клапан перекрывает канал в верхней части бурильной колонны. Он установлен под выходным валом СВП.","The ball valve shuts off the internal drillstring passage. It sits below the top drive output shaft.","rig","topdrive",["tds-quill"],["IBOP","шаровой кран"]],["rotary-table","Буровой ротор","Rotary table","Ротор размещён в полу над устьем. В классической схеме он передаёт момент ведущей трубе, а с СВП используется при удержании труб.","The rotary table is mounted in the drill floor above the well. It drives the kelly in a conventional system and supports pipe-handling equipment on a top-drive rig.","rig",null,["master-bushing","kelly-bushing"]],["master-bushing","Главный вкладыш ротора","Master bushing","Вкладыш установлен в центральном проёме ротора. В него садятся рабочие приспособления для удержания труб или привода квадрата.","The master bushing fits in the centre of the rotary table. It accepts the tools used to support pipe or drive the kelly."],["rotary-slips","Роторные клинья","Rotary slips","Сегменты клиньев охватывают трубу в конической посадке. Под весом колонны они удерживают трубу при отсоединении подвески.","Slip segments grip the pipe inside a tapered bowl. They support the string when the hoisting equipment is disconnected."],["kelly","Ведущая бурильная труба","Kelly","Гранёная труба скользит вертикально через приводной вкладыш. Грани передают вращение от ротора бурильной колонне.","The polygonal kelly slides through its drive bushing. Its faces transmit rotary table torque to the drillstring.","rig","kelly",["kelly-bushing","swivel"],["ведущая труба","квадрат"]],["kelly-bushing","Вкладыш ведущей трубы","Kelly bushing","Вкладыш вращается вместе с ротором. Его приводные поверхности передают момент ведущей трубе и допускают её осевой ход.","The bushing rotates with the rotary table. Its drive surfaces turn the kelly while allowing it to slide axially.","rig","kelly"],["swivel","Вертлюг","Swivel","Корпус вертлюга подвешен к крюку, а его ствол вращается вместе с ведущей трубой. Через вертлюг подводят буровой раствор.","The swivel housing hangs from the hook while its stem turns with the kelly. It admits drilling fluid to the rotating string.","rig","kelly"],["gooseneck","Отвод вертлюга","Swivel gooseneck","Изогнутый отвод направляет поток из бурового рукава в вертлюг. К нему присоединяется гибкий рукав высокого давления.","The curved inlet turns flow from the rotary hose into the swivel. It provides the connection point for the flexible high-pressure hose.","rig","kelly"],["iron-roughneck","Гидравлический буровой ключ","Iron roughneck","Узел захватывает две трубы по разные стороны резьбового соединения. Привод прикладывает момент при свинчивании и развинчивании.","The roughneck grips tubulars on either side of a threaded connection. Its hydraulic drive applies makeup or breakout torque.","rig",null,["rotary-slips"],["АКБ","гидроключ"]]],wc:[["casing-head","Колонная головка","Casing head","Нижний устьевой корпус соединён с обсадной колонной. Верхний фланец служит стыком для расположенного выше оборудования.","The lower wellhead housing is attached to a casing string. Its upper flange connects to the equipment above it.",wh,null,["annular-bop","drilling-spool"]],["annular-bop","Кольцевой превентор","Annular preventer","Кольцевой эластомерный элемент сжимается гидравликой. При закрытии он герметизирует пространство вокруг находящейся в проходе трубы.","Hydraulic pressure compresses an annular elastomeric element. The element can seal the opening around a tubular in the bore.",ln,null,["pipe-ram","bop-accumulator"],["универсальный превентор","annular BOP"]],["pipe-ram","Трубный плашечный превентор","Pipe ram preventer","Противолежащие плашки сходятся вокруг трубы заданного размера. Уплотнения перекрывают кольцевой зазор.","Opposing rams close around a tubular of the appropriate size. Their seals shut off the annular clearance.",ln,null,["blind-shear-ram","annular-bop"]],["blind-shear-ram","Превентор со срезающими плашками","Blind shear ram preventer","Срезающие плашки рассчитаны на определённые типы труб. После срезания предусмотренной трубы они могут герметизировать проход.","Blind shear rams are rated to cut specified tubulars. They can seal the bore after shearing a tubular within their design limits.",ln,null,["pipe-ram"],["срезающие плашки","blind shear ram","BSR"]],["ram-bonnet","Боковая крышка превентора","Ram preventer bonnet","Крышка закрывает боковую полость корпуса плашечного превентора. Узел даёт доступ к плашкам для обслуживания.","The bonnet closes the side cavity of the ram preventer. It provides access to the ram assembly for servicing.",ln],["drilling-spool","Противовыбросовая крестовина","Drilling spool","Крестовина имеет вертикальный проход и боковые отводы. Отводы связывают пространство ствола с линиями дросселирования и глушения.","The drilling spool has a vertical bore and side outlets. These outlets connect the wellbore to the choke and kill lines.",ln,null,["choke-line","kill-line"],["крестовина ПВО","BOP spool"]],["choke-line","Линия дросселирования","Choke line","Линия соединяет боковой отвод ПВО с дроссельным манифольдом. По ней отводят поток из скважины через узел регулирования.","The line connects a BOP outlet to the choke manifold. It routes well returns through the flow control equipment.",ln],["kill-line","Линия глушения","Kill line","Линия соединяет источник нагнетания с боковым отводом ПВО. Она позволяет подавать жидкость в скважину при закрытом превенторе.","The kill line connects a pumping source to a side outlet on the BOP stack. It provides a path for fluid into the well when a preventer is closed.",ln],["choke-manifold","Дроссельный манифольд","Choke manifold","Сборка труб, задвижек и дросселей направляет возвратный поток по выбранной ветви. Она расположена в стороне от устья.","The manifold uses piping, valves and chokes to route returns through a selected branch. It is positioned away from the wellhead.",ln,null,["choke-line","adjustable-choke"]],["adjustable-choke","Регулируемый дроссель","Adjustable choke","Проходное сечение дросселя изменяют для управления расходом и противодавлением. Он установлен на ветви манифольда.","Changing the choke opening controls flow and backpressure. The adjustable choke is installed on a manifold branch.",ln],["bop-gate-valve","Задвижка линии ПВО","BOP line gate valve","Запорный орган открывает или перекрывает ответвление. Штурвал связан с механизмом перемещения шибера.","The gate valve opens or isolates a branch of the BOP piping. The handwheel drives the gate mechanism.",ln],["bop-accumulator","Аккумуляторная установка ПВО","BOP accumulator unit","Гидроаккумуляторы хранят запас энергии для привода превенторов. Установка объединяет баллоны, насосы и распределение управляющей жидкости.","The accumulator bottles store energy for operating the preventers. The unit combines the bottles with pumps and hydraulic control equipment.",ln,null,["bop-control-panel"]],["bop-control-panel","Пульт управления превенторами","BOP control panel","На пульте находятся органы управления функциями ПВО. Он связан с гидравлической станцией управления.","The panel provides the operator’s controls for BOP functions. It is connected to the hydraulic control unit.",ln],["bop-control-lines","Гидролинии управления ПВО","BOP control lines","Линии соединяют станцию управления и исполнительные полости превенторов. По ним подводится рабочая жидкость.","The control lines link the hydraulic unit to the preventer actuators. They carry the operating fluid.",ln]]},xh=Object.entries(kh).flatMap(([l,a])=>a.map(([i,c,p,g,k,M="rig",f,m,_])=>({id:i,system:l,ru:c,en:p,descRu:g,descEn:k,stages:M,drive:f,related:m,aliases:_}))),Sh={mast:["mast-legs","mast-braces","mast-pins","mast-shoes"],"crown-block":["crown-sheaves"],"traveling-block":["traveling-sheaves","drilling-hook","elevator-links","elevator"],drawworks:["drawworks-drum","drawworks-brake","drawworks-motor"],"top-drive":["tds-motors","tds-gearbox","tds-quill","tds-handler","tds-guide","tds-carriage","upper-ibop"],"rotary-table":["master-bushing"],kelly:["kelly-bushing","swivel","gooseneck"],"choke-manifold":["adjustable-choke","bop-gate-valve"],"bop-accumulator":["bop-control-lines"],tree:["master-valve","production-wing-valve","swab-valve","production-choke","wellhead-gauge"],"pumping-unit-skid":["samson-post","walking-beam","horsehead","rod-bridle","carrier-bar","pumpjack-pitman","pumpjack-crank","crank-counterweight","pumpjack-gearbox","belt-drive","pumpjack-motor","pumpjack-brake"],"rod-pump-barrel":["rod-pump-plunger","standing-valve","traveling-valve"],"esp-pump":["esp-impeller","esp-diffuser"],"mud-pump":["mud-power-end","mud-fluid-end","mud-valve-cover","mud-pump-motor","mud-dampener","mud-relief-valve","mud-discharge-manifold","mud-suction-manifold"],"shale-shaker":["shaker-header","shaker-screen","shaker-vibrator"],"driller-cabin":["driller-console","driller-monitor","driller-joystick","driller-seat"],"generator-module":["diesel-engine","rig-alternator","diesel-radiator"],"cementing-unit":["cement-pump","cement-mixer","cement-surge-tank"],"wireline-truck":["wireline-winch","wireline-sheave","wireline-depth-wheel","wireline-console"],"tricone-bit":["roller-cone","bit-nozzle"],"pdc-bit":["pdc-cutter","bit-nozzle"]};function Js(l,a){return a.map(([i,c,p,g,k,M,f="rig",m])=>({id:i,system:l,ru:c,en:p,descRu:g,descEn:k,stages:f,related:M,aliases:m}))}const Do=[1,3,4,7],ei=[6,8],Eh=[...Js("circ",[["mud-pump","Трёхпоршневой буровой насос","Triplex mud pump","Подаёт буровой раствор под давлением в бурильную колонну. Три поршня работают со сдвигом фаз, чтобы уменьшить колебания подачи.","The pump delivers drilling fluid under pressure to the drillstring. Three reciprocating pistons run out of phase to smooth the delivery.",["mud-fluid-end","mud-discharge-manifold","standpipe"],"rig",["буровой насос","mud pump","triplex"]],["mud-power-end","Приводная часть бурового насоса","Mud pump power end","Преобразует вращение приводного вала в возвратно-поступательный ход поршней. Механизм расположен в закрытом корпусе и смазывается маслом.","The power end converts shaft rotation into reciprocating piston motion. Its gears and crank mechanism run inside a lubricated housing.",["mud-pump","mud-pump-motor"]],["mud-fluid-end","Гидравлическая часть бурового насоса","Mud pump fluid end","Вмещает цилиндры с поршнями, всасывающие и нагнетательные клапаны. Через неё раствор проходит от входного коллектора к линии высокого давления.","This assembly contains the piston-and-liner chambers and the suction and discharge valves. It routes mud from the inlet manifold into the high-pressure discharge line.",["mud-pump","mud-valve-cover","mud-discharge-manifold"]],["mud-valve-cover","Крышка клапанной коробки","Mud pump valve cover","Закрывает сервисное отверстие клапанной коробки гидравлической части. После снятия крышки можно обслуживать клапан и седло.","The cover closes a service opening in the fluid-end valve pot. Removing it provides access to the valve and its seat.",["mud-fluid-end","mud-pump"]],["mud-pump-motor","Электродвигатель бурового насоса","Mud pump drive motor","Вращает входной вал приводной части бурового насоса. Частотный привод позволяет менять число ходов поршней.","This motor drives the input shaft of the mud pump. A variable-frequency drive adjusts the stroke rate.",["mud-power-end","vfd-module"]],["mud-dampener","Компенсатор пульсаций","Discharge pulsation dampener","Газовая подушка за мембраной поглощает часть колебаний давления на выходе поршневого насоса. Корпус установлен на нагнетательном коллекторе.","A gas charge behind a diaphragm cushions pressure fluctuations at the reciprocating pump outlet. The vessel connects to the discharge manifold.",["mud-pump","mud-discharge-manifold"],"rig",["пневмокомпенсатор","pulsation damper"]],["mud-relief-valve","Предохранительный клапан бурового насоса","Mud pump discharge relief valve","Открывает путь сброса при превышении заданного давления на нагнетании. Защищает насос и трубопровод при ограничении потока.","The relief valve opens a bypass if discharge pressure exceeds its setting. It protects the pump and discharge circuit if flow is restricted.",["mud-discharge-manifold","mud-pump"]],["mud-discharge-manifold","Нагнетательный коллектор","Mud pump discharge manifold","Объединяет выходы гидравлической части поршневого насоса. От коллектора раствор идёт к стояку по линии высокого давления.","The manifold gathers flow from the pump discharge chambers. It sends pressurized mud toward the standpipe.",["mud-fluid-end","mud-dampener","mud-discharge-line"]],["mud-suction-manifold","Всасывающий коллектор","Mud pump suction manifold","Подводит раствор к всасывающим клапанам трёх цилиндров. На схеме расположен под нагнетательным коллектором.","The suction manifold feeds all three fluid-end chambers. In this layout it sits below the discharge manifold.",["mud-fluid-end","charge-pump","active-mud-tank"]],["mud-discharge-line","Линия высокого давления","High-pressure mud line","Соединяет нагнетание буровых насосов со стояком. На схеме параллельные ветви от двух насосов подходят к общему участку.","The high-pressure line connects the pump outlets to the standpipe. Both pump branches feed the common section shown here.",["mud-discharge-manifold","standpipe"]],["standpipe","Буровой стояк","Standpipe","Жёсткая вертикальная труба, закреплённая на мачте. Подаёт раствор из наземной нагнетательной линии к верхней точке бурового рукава.","The standpipe is a rigid vertical line secured to the mast. It carries mud from the surface discharge piping to the upper end of the rotary hose.",["mud-discharge-line","rotary-hose"],"rig",["нагнетательный стояк"]],["rotary-hose","Буровой рукав","Rotary hose","Гибкий рукав высокого давления соединяет стояк с подвижным входом раствора. Его петля позволяет верхнему приводу или вертлюгу перемещаться по высоте.","This flexible high-pressure hose connects the standpipe to the moving mud inlet. The loop accommodates travel of the top drive or swivel.",["standpipe","mud-discharge-line"],"rig",["буровой шланг","kelly hose"]],["mud-return-line","Линия возврата раствора","Mud return line","Принимает выходящий из кольцевого пространства раствор с выбуренной породой. Самотёком направляет его на блок вибросит.","Mud and cuttings leaving the annulus enter the return line. Gravity carries the flow to the shaker header box.",["shaker-header","shale-shaker"],"rig",["желобная система","flowline"]],["shaker-header","Распределительный короб вибросит","Shaker header box","Принимает поток из возвратной линии и распределяет его по виброситам. Параллельные ветви позволяют обслуживать один аппарат при работе другого.","The header box receives flow from the return line and distributes it among the shakers. Parallel outlets make it possible to service one unit while another runs.",["mud-return-line","shale-shaker"]],["shale-shaker","Вибросито","Shale shaker","Первым удаляет основную массу крупного шлама после выхода раствора из скважины. Жидкость проходит сквозь сетку, а твёрдая фаза движется к разгрузке.","The shaker is the first stage of coarse cuttings removal. Fluid passes through its screens while vibration conveys retained solids to the discharge end.",["shaker-screen","shaker-vibrator","cuttings-bin"],"rig",["вибрационное сито"]],["shaker-screen","Сетка вибросита","Shaker screen","Задерживает частицы крупнее отверстий сетки и пропускает жидкость. Сменные панели опираются на вибрирующую корзину.","The screen retains particles larger than its openings while passing fluid. Exchangeable panels rest on the vibrating basket.",["shale-shaker","cuttings-bin"]],["shaker-vibrator","Вибродвигатель вибросита","Shaker vibrator motor","Эксцентриковые грузы создают колебания корзины с сетками. Движение помогает перемещать удержанный шлам к разгрузочной кромке.","Eccentric weights generate motion in the screen basket. That motion moves the retained solids toward the discharge edge.",["shale-shaker","shaker-screen"]],["cuttings-bin","Шламовый контейнер","Cuttings bin","Собирает выбуренную породу и влажный шлам с оборудования очистки. Установлен у разгрузочного края вибросит.","The bin receives drilled cuttings discharged by the solids-control equipment. It sits below the shaker discharge end.",["shale-shaker","shaker-screen"]],["settling-mud-tank","Приёмная ёмкость раствора","Shaker tank","Собирает раствор, прошедший сквозь сетки вибросит. Отсюда поток направляют на дальнейшую очистку по схеме циркуляционной системы.","The shaker tank catches fluid passing through the primary screens. Further processing takes place downstream of this tank.",["shaker-screen","desander","active-mud-tank"],"rig",["приёмный отсек","sand trap"]],["active-mud-tank","Рабочая ёмкость раствора","Active mud tank","Вмещает часть объёма бурового раствора, находящегося в циркуляции. Из последнего рабочего отсека насосы забирают раствор для подачи обратно в скважину.","The active tank holds part of the circulating drilling-fluid volume. The pumps take suction from the final active compartment.",["mud-agitator","charge-pump","reserve-mud-tank"],"rig",["приёмный резервуар","suction tank"]],["reserve-mud-tank","Запасная ёмкость раствора","Reserve mud tank","Хранит приготовленный раствор или дополнительный запас объёма. Запас подключают к рабочей системе по мере необходимости.","The reserve tank holds premixed fluid or additional usable volume. This capacity can be transferred into the active system as needed.",["active-mud-tank","mud-hopper"]],["mud-agitator","Перемешиватель бурового раствора","Mud agitator","Вращает лопасти под поверхностью раствора, удерживая твёрдую фазу во взвеси. На макете приводы расположены над отсеками ёмкостей.","An immersed impeller keeps solids suspended in the tank. The drive motors are mounted above the compartments.",["active-mud-tank","reserve-mud-tank"]],["charge-pump","Подпорный насос","Mud pump charge pump","Подаёт раствор из рабочей ёмкости к входу основного бурового насоса. Подпор помогает наполнять цилиндры при обратном ходе поршней.","This centrifugal pump feeds mud from the active tank to the triplex inlet. A positive suction head helps fill the cylinders on their intake strokes.",["active-mud-tank","mud-suction-manifold"],"rig",["подкачивающий насос","charging pump"]],["desander","Пескоотделитель","Desander","Группа гидроциклонов отделяет более крупные частицы из раствора после вибросит. Конусы сбрасывают концентрированный поток твёрдой фазы снизу.","This hydrocyclone bank removes relatively coarse solids downstream of the shakers. A concentrated solids stream leaves the bottom of each cone.",["desilter","settling-mud-tank"]],["desilter","Илоотделитель","Desilter","Батарея гидроциклонов меньшего диаметра отделяет более мелкие частицы. В данной компоновке расположен после пескоотделителя.","A bank of smaller hydrocyclones targets finer particles. It follows the desander in the illustrated installation.",["desander","mud-centrifuge"]],["mud-degasser","Вакуумный дегазатор","Vacuum degasser","При пониженном давлении удаляет газ, диспергированный в растворе. Включён в наземную систему очистки раствора.","Reduced pressure helps remove entrained gas from the mud. The unit is installed within the surface processing system.",["degasser-vacuum-pump","settling-mud-tank"]],["degasser-vacuum-pump","Вакуумный насос дегазатора","Degasser vacuum pump","Создаёт разрежение в корпусе дегазатора. По отдельному патрубку отводит выделившийся газ.","The vacuum pump reduces pressure inside the degasser vessel. Its separate outlet routes the separated gas away.",["mud-degasser"]],["mud-centrifuge","Декантерная центрифуга","Decanter centrifuge","В быстро вращающемся барабане разделяет потоки по плотности. Применяется для удаления тонкодисперсной твёрдой фазы или управления составом раствора.","A high-speed bowl separates streams according to density. Operators use it to remove fine solids or manage the mud composition.",["desilter","cuttings-bin"]],["mud-hopper","Смесительная воронка","Mud mixing hopper","Подаёт сухие добавки в движущийся поток раствора. Сужение под воронкой создаёт перепад давления для ввода и перемешивания материала.","The hopper introduces dry additives into moving drilling fluid. A constriction below it creates the pressure difference that entrains and disperses the material.",["reserve-mud-tank","active-mud-tank"],"rig",["гидроворонка","jet hopper"]],["trip-tank","Ёмкость долива","Trip tank","Небольшой калиброванный резервуар помогает измерять объём долива и вытеснения при спуско-подъёмных операциях. Изменения уровня сравнивают с ожидаемым объёмом.","A small calibrated tank measures fluid added or displaced while tripping. Crew members compare the level change with the expected volume.",["mud-return-line","active-mud-tank"],"rig",["доливная ёмкость"]]]),...Js("power",[["driller-cabin","Кабина бурильщика","Driller’s cabin","Защищённый пост управления на буровой площадке. Из кабины видна рабочая зона ротора и доступны органы управления установкой.","The cabin houses the rig controls on the drill floor. Its position gives the driller a view of the rotary work area.",["driller-console","driller-monitor","driller-seat"],"rig",["пост бурильщика","driller’s control cabin"]],["driller-console","Пульт бурильщика","Driller’s control console","Объединяет команды управления подъёмом, вращением и подачей раствора. Расположен перед креслом в кабине.","The console groups the controls for hoisting, rotation and mud delivery. It is positioned in front of the driller’s chair.",["driller-cabin","driller-joystick","driller-monitor"]],["driller-monitor","Мониторы бурильщика","Driller’s display monitors","Показывают параметры бурения, включая нагрузку, давление и частоту вращения. Оператор наблюдает за ними при управлении оборудованием.","The displays present drilling measurements including load, pressure and rotary speed. The driller refers to them while operating equipment.",["driller-console","driller-joystick"]],["driller-joystick","Джойстики бурильщика","Driller’s control joysticks","Служат для подачи команд приводам с кресла оператора. Назначение рукояток зависит от выбранной системы управления.","The joysticks send motion commands from the operator’s chair. Each handle’s function depends on the rig’s control arrangement.",["driller-console","driller-seat"]],["driller-seat","Кресло бурильщика","Driller’s chair","Рабочее место оператора в кабине. Кресло расположено перед экранами и рядом с рукоятками управления.","The chair is the operator’s workstation inside the cabin. It faces the displays with the control handles close at hand.",["driller-cabin","driller-monitor"]],["generator-module","Дизель-генераторная станция","Diesel generator set","Преобразует энергию топлива в электрическую энергию для буровой. Комплект размещён на общей раме внутри вентилируемого модуля.","The generator set converts fuel energy into electricity for the rig. Its machinery shares a common base in a ventilated enclosure.",["diesel-engine","rig-alternator","switchgear"],"rig",["ДГУ","genset"]],["diesel-engine","Дизельный двигатель станции","Generator diesel engine","Вращает вал генератора, используя энергию сгорания дизельного топлива. В модуле расположен между радиатором и электрической машиной.","The engine uses diesel fuel to turn the generator shaft. It sits between the radiator and the electrical machine.",["generator-module","rig-alternator","diesel-radiator"]],["rig-alternator","Синхронный генератор","Rig alternator","Преобразует вращение от дизеля в переменный ток. Через распределительное устройство питает электрические системы установки.","The alternator converts engine rotation into alternating current. It feeds the rig electrical system through the switchgear.",["diesel-engine","switchgear"]],["diesel-radiator","Радиатор дизельного двигателя","Diesel engine radiator","Отводит тепло из охлаждающей жидкости двигателя в воздух. Поток воздуха через теплообменник обеспечивает вентилятор.","The radiator rejects engine-coolant heat to the air. A fan forces air through its heat-exchanger core.",["diesel-engine","generator-module"]],["switchgear","Распределительное устройство","Rig switchgear","Распределяет электроэнергию генераторов по потребителям. Встроенные аппараты позволяют коммутировать цепи и отключать их при неисправностях.","Switchgear distributes generator output to the rig loads. Its devices switch circuits and interrupt them under fault conditions.",["generator-module","vfd-module"]],["vfd-module","Блок частотных преобразователей","Variable-frequency drive module","Регулирует скорость электроприводов изменением частоты питания. Такие приводы применяются для лебёдки, ротора и буровых насосов в соответствующей комплектации.","The module varies the supply frequency to control motor speed. Drives of this kind can serve the drawworks, rotary equipment and mud pumps.",["switchgear","mud-pump-motor"],"rig",["ПЧ","VFD","variable speed drive"]],["rig-fuel-tank","Топливная ёмкость буровой","Rig diesel fuel tank","Содержит запас дизельного топлива для генераторных станций. Установлена на самостоятельном поддоне за энергетическим блоком.","The tank stores diesel for the power modules. It stands in a dedicated containment tray near the generating area.",["generator-module","diesel-engine"]],["doghouse","Культбудка","Doghouse","Бытовое помещение бригады рядом с установкой. Используется для перерывов, хранения рабочих документов и мелкого инвентаря.","This crew shelter stands near the rig. It provides space for breaks, working records and small items of equipment.",[],"rig",["вагон-бытовка","crew shelter"]],["cable-tray","Силовой кабельный лоток","Power cable tray","Поддерживает электрические кабели на пути от распределительных шкафов к приводам. Приподнятая трасса убирает часть проводки с рабочей поверхности площадки.","The tray supports electrical cables between the power cabinets and driven equipment. Its raised route keeps part of the cabling off the working surface.",["switchgear","vfd-module"]]]),...Js("str",[["manual-tongs","Машинный буровой ключ","Manual rig tongs","Захватывает замок бурильной трубы и передаёт крутящий момент через длинный рычаг. На площадке два ключа позволяют удерживать одну часть соединения и вращать другую.","The jaws grip a drill-pipe tool joint and the long handle transmits torque. A pair of tongs can hold one side of the connection while the other side turns.",["iron-roughneck","tong-snub-line"],"rig",["машинные ключи","manual tongs","backup tongs"]],["tong-snub-line","Страховой канат машинного ключа","Tong snub line","Ограничивает перемещение рукоятки ключа под нагрузкой. Канат соединяет рукоятку с точкой крепления на конструкции буровой.","The line restrains the tong handle under load. It connects the handle to an anchor on the rig structure.",["manual-tongs"],"rig",["удерживающий канат","snub-line"]]]),...Js("service",[["cementing-unit","Цементировочный агрегат","Cementing unit","Мобильный агрегат нагнетает тампонажный раствор и продавочную жидкость при креплении скважины. Насос работает совместно со смесительной системой.","The mobile unit pumps cement slurry and displacement fluid during casing cementing. Its high-pressure pump works in conjunction with the mixing system.",["cement-pump","cement-mixer","cement-iron"],Do],["cement-pump","Насос цементировочного агрегата","High-pressure cement pump","Плунжерный насос поднимает давление раствора перед подачей в обсадную колонну. Его гидравлическая часть находится на платформе агрегата.","This plunger pump raises slurry pressure before injection into the casing. The fluid end is mounted on the cementing unit’s working deck.",["cementing-unit","cement-iron"],Do],["cement-mixer","Цементосмесительная установка","Cement slurry mixing unit","Дозирует воду затворения и сухой цемент, формируя тампонажный раствор. Поток проходит через смеситель перед подачей на цементировочный насос.","The mixing unit combines measured amounts of water and dry cement into a slurry. The slurry passes through the mixing system before entering the cement pump.",["cementing-unit","cement-surge-tank"],Do],["cement-surge-tank","Приёмная ёмкость цементного раствора","Cement slurry surge tank","Принимает приготовленный раствор и сглаживает кратковременные различия между смешиванием и забором. Соединена со всасыванием насоса агрегата.","The tank receives freshly mixed slurry and buffers short-term differences between mixing and pump intake rates. It feeds the cementing unit’s suction connection.",["cement-mixer","cement-pump"],Do],["cement-iron","Нагнетательная линия цементирования","Cementing treating iron","Секции труб и шарнирные соединения проводят раствор высокого давления от насосного агрегата к цементировочной головке. Линию собирают на площадке на время операции.","Jointed high-pressure piping carries cement slurry from the unit to the cementing head. The piping is assembled on location for the job.",["cement-pump","cement-head"],Do,["цементировочная обвязка","cementing line"]],["cement-head","Цементировочная головка","Cementing head","Присоединяется к верхнему концу обсадных труб и принимает поток от цементировочного агрегата. В её корпусе размещаются пробки, которые выпускают при цементировании.","The cementing head connects the casing to the pump line. It houses cementing plugs for release during the job.",["cement-iron","cementing-unit"],Do],["wireline-truck","Каротажная станция","Wireline logging unit","Автомобильная станция вмещает подъёмник и наземную аппаратуру. Оператор управляет прибором и записывает данные, поступающие с глубины.","The truck-mounted unit houses the winch and surface instrumentation. The operator controls the sonde and records data transmitted from downhole.",["wireline-winch","wireline-console","wireline-depth-wheel"],ei,["каротажная лаборатория","logging truck"]],["wireline-winch","Каротажный подъёмник","Wireline winch","Сматывает и наматывает каротажный кабель для перемещения прибора. Барабан установлен со стороны выхода кабеля из каротажной станции.","The winch pays out and retrieves the cable to move the logging tool. Its drum is mounted beside the cable exit of the logging unit.",["wireline-truck","wireline-sheave","wireline-depth-wheel"],ei],["wireline-sheave","Направляющий ролик каротажного кабеля","Wireline sheave","Изменяет направление кабеля с наземной трассы на вертикальную ось скважины. Подвешен над устьем на время работ.","The sheave redirects cable from the surface run down into the well. It is suspended above the well center for the operation.",["wireline-winch","wireline-depth-wheel"],[6]],["wireline-depth-wheel","Мерный ролик каротажного кабеля","Wireline depth wheel","Прижат к движущемуся кабелю и передаёт обороты измерителю глубины. Система использует количество оборотов для расчёта пройденного расстояния.","The measuring wheel turns against the moving cable and drives the depth recorder. Wheel revolutions are used to calculate cable travel.",["wireline-winch","wireline-console"],ei],["wireline-console","Пульт каротажной станции","Wireline acquisition console","Принимает сигналы скважинных приборов и сохраняет измерения с привязкой к глубине. Размещён в аппаратном отсеке перед подъёмником.","The console receives tool signals and records measurements against depth. It is housed in the instrumentation compartment ahead of the winch.",["wireline-truck","wireline-depth-wheel"],ei],["staged-perforating-gun","Корпус перфоратора","Perforating gun carrier","Удерживает кумулятивные заряды, ориентированные для создания каналов через колонну и цемент. На макете показан на поверхности рядом с каротажной станцией после осмотра зоны перфорации.","The carrier houses shaped charges oriented to create tunnels through casing and cement. Here it is illustrated on the surface beside the wireline unit for comparison with the completed interval.",["wireline-truck"],[8],["кумулятивный перфоратор","perforating gun"]]])],or=l=>new an(...l),Mh=.035,zh=.12,Th=.16;function Ch(l,a,i,c){const p=[l/2,a/2,i/2],g=p.map(L=>L-c),k=[],M=[],f=[],m=(L,C,N)=>{const T=(C+1)%3,x=(C+2)%3,z=L.map((F,D)=>F*(D===C?p[D]:g[D]));z[C]=N*p[C];const O=[0,0,0];O[C]=N;const R=[(z[T]/p[T]+1)/2,(z[x]/p[x]+1)/2];return{position:z,normal:O,uv:R}},_=(L,C,N)=>{const T=L.position.map((R,F)=>C.position[F]-R),x=L.position.map((R,F)=>N.position[F]-R),O=[T[1]*x[2]-T[2]*x[1],T[2]*x[0]-T[0]*x[2],T[0]*x[1]-T[1]*x[0]].reduce((R,F,D)=>R+F*(L.normal[D]+C.normal[D]+N.normal[D]),0);for(const R of O>=0?[L,C,N]:[L,N,C])k.push(...R.position),M.push(...R.normal),f.push(...R.uv)},j=(L,C,N,T)=>{_(L,C,N),_(L,N,T)},S=[-1,1];for(let L=0;L<3;L++)for(const C of S){const N=(L+1)%3,T=(L+2)%3,x=(z,O)=>{const R=[0,0,0];return R[L]=C,R[N]=z,R[T]=O,m(R,L,C)};j(x(-1,-1),x(1,-1),x(1,1),x(-1,1))}for(let L=0;L<3;L++)for(let C=L+1;C<3;C++){const N=3-L-C;for(const T of S)for(const x of S){const z=O=>{const R=[0,0,0];return R[L]=T,R[C]=x,R[N]=O,R};j(m(z(-1),L,T),m(z(1),L,T),m(z(1),C,x),m(z(-1),C,x))}}for(const L of S)for(const C of S)for(const N of S){const T=[L,C,N];_(m(T,0,L),m(T,1,C),m(T,2,N))}const Y=new hd;return Y.setAttribute("position",new Oo(k,3)),Y.setAttribute("normal",new Oo(M,3)),Y.setAttribute("uv",new Oo(f,2)),Y.computeBoundingBox(),Y.computeBoundingSphere(),Y}const Ph=(l,a,i)=>{const c=Math.min(Math.abs(l),Math.abs(a),Math.abs(i));return c<Th?0:Math.min(Mh,zh*c)},Jd=(l,a,i)=>{const c=Ph(l,a,i);return c?Ch(Math.abs(l),Math.abs(a),Math.abs(i),c):new Y1(l,a,i)},d=(l,a,i,c,p,g)=>Jd(l,a,i).translate(c,p,g);function h(l,a,i,c,p,g,k="y",M=20){const f=new mu(l,a,i,M);return k==="x"&&f.rotateZ(Math.PI/2),k==="z"&&f.rotateX(Math.PI/2),f.translate(c,p,g)}